import { createMemo } from "solid-js";
import { tracked } from "./tracked";

interface PkgApi {
  get(): (s: () => number) => void;
}
declare const api: PkgApi;

// The callee is exactly a local arrow whose body hands the parameter to a
// tracked primitive: nothing undescribed is reached.
export function exact(source: () => number): () => number {
  const fn = (s: () => number) => createMemo(s);
  return fn(source);
}

// The same, through another module's exact function.
export function forwarded(source: () => number): () => number {
  return tracked(source);
}

// The undescribed callee receives an inner binding of the same name, not the
// parameter.
export function shadowed(source: () => number): void {
  {
    const source = () => 1;
    const fn = api.get();
    fn(source);
  }
}
